export const AVATAR_PRESET_KEYS = Object.keys(AVATAR_PRESET_IMAGES);

export function getRankBadgeImage(tier: RankTier, division: 0 | 1 | 2 | 3 = 1): ImageSourcePropType | null {
  if (tier === 'Unranked') return null;
  const low = tier.toLowerCase();
  if (low === 'olympian') return RANK_BADGE_IMAGES.olympian ?? null;
  const div = Math.max(1, Math.min(3, division || 1));
  return RANK_BADGE_IMAGES[`${low}${div}`] ?? RANK_BADGE_IMAGES[`${low}1`] ?? null;
}

export function getRankGlowImage(tier: RankTier): ImageSourcePropType | null {
  if (tier === 'Unranked') return null;
  return RANK_GLOW_IMAGES[tier.toLowerCase()] ?? null;
}

export function getExerciseAvatarImage(exerciseId: string): ImageSourcePropType | null {
  return EXERCISE_AVATAR_IMAGES[exerciseId] ?? null;
}

export function getExerciseFullImage(exerciseId: string): ImageSourcePropType | null {
  return EXERCISE_FULL_IMAGES[exerciseId] ?? EXERCISE_AVATAR_IMAGES[exerciseId] ?? null;
}

export function getEquipmentImage(equipment: string): ImageSourcePropType | null {
  return EQUIPMENT_IMAGES[equipment] ?? null;
}

export function getProfileBorderAsset(borderId?: string | null): {
  front?: ImageSourcePropType;
  back?: ImageSourcePropType;
  rotateBack?: boolean;
  rotateFront?: boolean;
} {
  switch (borderId) {
    case 'shp_border_gold':
      return {
        front: PROFILE_BORDER_IMAGES.solarborderfront,
        back: PROFILE_BORDER_IMAGES.solarborderback,
        rotateBack: true,
      };
    case 'shp_border_amethyst':
      return {
        front: PROFILE_BORDER_IMAGES.asteroidouterring,
        back: PROFILE_BORDER_IMAGES.asteroidinnerring,
        rotateFront: true,
        rotateBack: true,
      };
    case 'shp_border_sky':
      return { front: PROFILE_BORDER_IMAGES.waterborder };
    case 'shp_border_fire':
      return { front: PROFILE_BORDER_IMAGES.fireborder };
    case 'shp_border_moon':
      return { front: PROFILE_BORDER_IMAGES.moonborder };
    case 'shp_border_premium':
      return { front: PROFILE_BORDER_IMAGES.premiumborder };
    default:
      return {};
  }
}

export function getProfileBannerAsset(bannerId?: string | null): ImageSourcePropType | null {
  switch (bannerId) {
    case 'shp_banner_cyber':
      return PROFILE_BANNER_IMAGES.constellation ?? null;
    case 'shp_banner_crimson':
      return PROFILE_BANNER_IMAGES.fireworks ?? null;
    case 'shp_banner_winter':
      return PROFILE_BANNER_IMAGES.winter ?? null;
    case 'shp_banner_plains':
      return PROFILE_BANNER_IMAGES.plains ?? null;
    case 'shp_banner_fall':
      return PROFILE_BANNER_IMAGES.fall ?? null;
    default:
      return PROFILE_BANNER_IMAGES.constellation ?? null;
  }
}

export function getArchetypeImage(archetype: string): ImageSourcePropType | null {
  const low = archetype.toLowerCase();
  if (low.includes('titan') || low.includes('atlas')) return ARCHETYPE_IMAGES.atlas ?? null;
  if (low.includes('grinder') || low.includes('engine')) return ARCHETYPE_IMAGES.engine ?? null;
  if (low.includes('gladiator') || low.includes('challenger')) return ARCHETYPE_IMAGES.gladiator ?? null;
  return ARCHETYPE_IMAGES.athlete ?? null;
}
